import math
from itertools import combinations

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd_three(a, b, c):
    return gcd(a, gcd(b, c))

def is_good_set(U):
    if len(U) < 3:
        return False

    # Constraint 2: GCD of any three distinct elements is 1
    for triplet in combinations(U, 3):
        if gcd_three(*triplet) != 1:
            return False

    # Constraint 3: For any two distinct elements, there exists another element that divides their product
    for pair in combinations(U, 2):
        u_i, u_j = pair
        product = u_i * u_j

        found_divisor = False
        # Check against elements in U excluding u_i and u_j
        for u_k in U:
            if u_k != u_i and u_k != u_j:
                if product % u_k == 0:
                    found_divisor = True
                    break

        if not found_divisor:
            return False

    return True

# Search for good sets U where max(U) <= 20 and |U| = 3
U_candidates = []
# Iterate through combinations of 3 distinct integers >= 2
for u1 in range(2, 21):
    for u2 in range(u1 + 1, 21):
        for u3 in range(u2 + 1, 21):
            U = tuple(sorted((u1, u2, u3)))
            if is_good_set(U):
                U_candidates.append(U)

# Calculate the product m for each good set found
good_numbers = set()
for U in U_candidates:
    m = U[0] * U[1] * U[2]
    good_numbers.add(m)

sorted_good_numbers = sorted(list(good_numbers))

print("Found Good Sets U (max element <= 20):")
for U in U_candidates:
    m = U[0] * U[1] * U[2]
    print(f"U={U}, m={m}")

print("\nSorted Good Numbers (from sets with max element <= 20):")
print(sorted_good_numbers)

