import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd_triple(a, b, c):
    return gcd(a, gcd(b, c))

def find_N(limit):
    N_values = set()

    # Search for x, y, z such that 2 <= x < y < z and they are pairwise coprime
    for x in range(2, limit // 6 + 1):
        for y in range(x + 1, limit // 3 + 1):
            if gcd(x, y) != 1:
                continue
            for z in range(y + 1, limit // 2 + 1):
                if gcd(x, z) == 1 and gcd(y, z) == 1:
                    N_values.add(x * y * z)

    return sorted(list(N_values))

# We need the 20th smallest N. Let's estimate an upper bound for the 20th N.
# N=30, 42, 66, 70, 78, 102, 105, 110. The 20th should be perhaps around 200-300.
# Let's search up to a limit where we expect at least 20 results.
N_list = find_N(400)
print(f"Found {len(N_list)} values of N up to 400.")
print("First 20 values of N:")
for i, n in enumerate(N_list[:20]):
    print(f"{i+1}: {n}")

import math
from itertools import combinations, product

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def is_pairwise_coprime(d_list):
    for i in range(len(d_list)):
        for j in range(i + 1, len(d_list)):
            if gcd(d_list[i], d_list[j]) != 1:
                return False
    return True

# We are looking for the 20th smallest N = d1 * d2 * d3 where d1, d2, d3 >= 2
# and they are pairwise coprime.
N_values = set()

# We search for d1, d2, d3 up to a reasonable limit (e.g., 20, since the 20th N is likely around 180-250)
limit = 20
for d1 in range(2, limit + 1):
    for d2 in range(d1 + 1, limit + 1):
        if gcd(d1, d2) != 1:
            continue
        for d3 in range(d2 + 1, limit + 1):
            if gcd(d1, d3) != 1:
                continue
            if gcd(d2, d3) != 1:
                continue

            N = d1 * d2 * d3
            N_values.add(N)

sorted_N = sorted(list(N_values))

print("List of N values found (first 25):")
print(sorted_N[:25])

if len(sorted_N) >= 20:
    N_20th = sorted_N[19] # 0-indexed
    print(f"The 20th smallest N is: {N_20th}")
else:
    print("Could not find 20 values within the current search limit.")
